function stripEmoji(text){
  text=String(text==null?'':text);
  var re=/\p{Extended_Pictographic}|\uFE0F|\u200D/gu;
  var removed=text.match(re)||[];
  var out=text.replace(re,'').replace(/\s{2,}/g,' ').trim();
  return {text:out, removed:removed.length, count:removed.length};
}
var EXPORTS={stripEmoji:stripEmoji};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EmojiStripForgePure = EXPORTS; }
